import type { CliCommandResult, CliEnvelope } from './envelope';
import { serializeEnvelope } from './envelope';

export type CliIO = {
  writeEnvelope: (envelope: CliEnvelope) => void;
  writeProgress: (message: string) => void;
};

export const processCliIO: CliIO = {
  writeEnvelope: (envelope) => {
    process.stdout.write(`${serializeEnvelope(envelope)}\n`);
  },
  writeProgress: (message) => {
    process.stderr.write(`${message}\n`);
  },
};

export const emitResult = (io: CliIO, result: CliCommandResult): number => {
  io.writeEnvelope(result.envelope);
  return result.exitCode;
};
